import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { createClient } from "npm:@supabase/supabase-js@2";
import {
  corsHeaders,
  jsonResponse,
  parseQueryInt,
  requireCronAuth,
} from "../_shared/http.ts";
import { beginIdempotency, finishIdempotency } from "../_shared/pncp/idempotency.ts";

function getUserClient(req: Request) {
  const url = Deno.env.get("SUPABASE_URL");
  const anon = Deno.env.get("SUPABASE_ANON_KEY");
  if (!url || !anon) throw new Error("Supabase env missing");
  return createClient(url, anon, {
    global: { headers: { Authorization: req.headers.get("Authorization") ?? "" } },
    auth: { persistSession: false },
  });
}

async function triggerSync(tipo: string, body: Record<string, unknown>) {
  const base = Deno.env.get("SUPABASE_URL")?.replace(/\/+$/, "");
  const secret = Deno.env.get("SYNC_CRON_SECRET");
  if (!base || !secret) throw new Error("Sync não configurado");
  const fnMap: Record<string, string> = {
    editais: "sync-pncp-contratacoes-editais",
    atas: "sync-pncp-contratacoes-atas",
    contratos: "sync-pncp-contratacoes-contratos",
  };
  const fn = fnMap[tipo];
  if (!fn) throw new Error("tipo inválido: editais | atas | contratos");
  const res = await fetch(`${base}/functions/v1/${fn}`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${secret}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify(body),
  });
  return { status: res.status, body: await res.json() };
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });
  const url = new URL(req.url);
  const tipo = url.searchParams.get("tipo") ?? "editais";

  if (req.method === "GET") {
    const client = getUserClient(req);
    const page = parseQueryInt(url, "page", 1);
    const limit = Math.min(parseQueryInt(url, "limit", 20), 100);
    const offset = (page - 1) * limit;
    const tableMap: Record<string, string> = {
      editais: "contratacoes_editais",
      atas: "contratacoes_atas",
      contratos: "contratacoes_contratos",
    };
    const table = tableMap[tipo] ?? "contratacoes_editais";

    const { data, error, count } = await client
      .from(table)
      .select("*", { count: "exact" })
      .eq("ativo", true)
      .order("updated_at", { ascending: false })
      .range(offset, offset + limit - 1);

    if (error) return jsonResponse({ error: error.message }, 400);
    return jsonResponse({ tipo, data, page, limit, total: count ?? 0 });
  }

  if (req.method === "POST") {
    const denied = requireCronAuth(req);
    if (denied) return denied;

    const idempotencyKey = req.headers.get("Idempotency-Key");
    if (!idempotencyKey) {
      return jsonResponse({ error: "Header Idempotency-Key obrigatório" }, 400);
    }

    const serviceUrl = Deno.env.get("SUPABASE_URL");
    const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
    if (!serviceUrl || !serviceKey) {
      return jsonResponse({ error: "Service role não configurado" }, 500);
    }

    const admin = createClient(serviceUrl, serviceKey, {
      auth: { persistSession: false },
    });

    const body = await req.json().catch(() => ({}));
    const rota = `POST /api/contratacoes/sync?tipo=${tipo}`;
    const begin = await beginIdempotency(admin, idempotencyKey, rota, { ...body, tipo });
    if (begin.skip) return jsonResponse(begin.resposta);

    const result = await triggerSync(tipo, body);
    await finishIdempotency(admin, idempotencyKey, rota, result.body, result.status);
    return jsonResponse(result.body, result.status);
  }

  return jsonResponse({ error: "Method not allowed" }, 405);
});

export const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type, idempotency-key",
  "Access-Control-Allow-Methods": "GET, POST, PATCH, OPTIONS",
};

export type AuthDecision =
  | "CRON_AUTHENTICATED"
  | "USER_AUTHENTICATED"
  | "REJECTED";

export function jsonResponse(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: {
      ...corsHeaders,
      "Content-Type": "application/json; charset=utf-8",
    },
  });
}

export function errorDetail(error: unknown): string {
  if (error instanceof Error) return error.message;
  if (error && typeof error === "object") {
    const record = error as Record<string, unknown>;
    const parts = [record.message, record.details, record.hint, record.code]
      .filter((part) => typeof part === "string" && part.length > 0);
    if (parts.length > 0) return parts.join(" | ");
    try {
      return JSON.stringify(error);
    } catch {
      return String(error);
    }
  }
  return String(error);
}

/** Extract Bearer token; empty/malformed → null. Does NOT authenticate. */
export function extractBearerToken(req: Request): string | null {
  const auth = req.headers.get("Authorization");
  if (auth == null) return null;
  const trimmed = auth.trim();
  if (!trimmed.toLowerCase().startsWith("bearer ")) return null;
  const token = trimmed.slice("bearer ".length).trim();
  return token.length > 0 ? token : null;
}

/**
 * Cron auth: exact match of Bearer token to SYNC_CRON_SECRET.
 * Fail-closed if secret missing/empty. Presence of "Bearer " is never enough.
 */
export function authenticateCron(req: Request): AuthDecision {
  const secret = Deno.env.get("SYNC_CRON_SECRET")?.trim();
  if (!secret) return "REJECTED";
  const token = extractBearerToken(req);
  if (!token) return "REJECTED";
  return token === secret ? "CRON_AUTHENTICATED" : "REJECTED";
}

/** @deprecated Prefer authenticateCron; kept for sync-* call sites. */
export function validateCronAuth(req: Request): boolean {
  return authenticateCron(req) === "CRON_AUTHENTICATED";
}

/**
 * Require cron secret for privileged sync triggers.
 * Returns 401 Response on failure; null when CRON_AUTHENTICATED.
 */
export function requireCronAuth(req: Request): Response | null {
  if (authenticateCron(req) === "CRON_AUTHENTICATED") return null;
  return jsonResponse({ error: "Unauthorized" }, 401);
}

/**
 * Validate Supabase Auth JWT (user session). Fail-closed on missing env/token/user.
 * Does not treat cron secret as a user session.
 */
export async function authenticateUserJwt(req: Request): Promise<AuthDecision> {
  const token = extractBearerToken(req);
  if (!token) return "REJECTED";

  const cronSecret = Deno.env.get("SYNC_CRON_SECRET")?.trim();
  if (cronSecret && token === cronSecret) {
    // Cron is not a user identity for signed-URL / user-scoped routes.
    return "REJECTED";
  }

  const url = Deno.env.get("SUPABASE_URL")?.trim();
  const anon = Deno.env.get("SUPABASE_ANON_KEY")?.trim();
  if (!url || !anon) return "REJECTED";

  try {
    const { createClient } = await import("npm:@supabase/supabase-js@2");
    const client = createClient(url, anon, {
      auth: { persistSession: false, autoRefreshToken: false },
    });
    const { data, error } = await client.auth.getUser(token);
    if (error || !data.user) return "REJECTED";
    return "USER_AUTHENTICATED";
  } catch {
    return "REJECTED";
  }
}

export async function requireUserAuth(req: Request): Promise<Response | null> {
  if ((await authenticateUserJwt(req)) === "USER_AUTHENTICATED") return null;
  return jsonResponse({ error: "Unauthorized" }, 401);
}

/**
 * Cron OR authenticated user (for ops that allow either).
 * Still fail-closed; never accepts arbitrary Bearer strings.
 */
export async function authenticateCronOrUser(req: Request): Promise<AuthDecision> {
  const cron = authenticateCron(req);
  if (cron === "CRON_AUTHENTICATED") return cron;
  return await authenticateUserJwt(req);
}

export async function requireCronOrUserAuth(req: Request): Promise<Response | null> {
  const decision = await authenticateCronOrUser(req);
  if (decision === "CRON_AUTHENTICATED" || decision === "USER_AUTHENTICATED") {
    return null;
  }
  return jsonResponse({ error: "Unauthorized" }, 401);
}

export function parseQueryInt(
  url: URL,
  key: string,
  fallback: number,
): number {
  const raw = url.searchParams.get(key);
  if (!raw) return fallback;
  const n = Number.parseInt(raw, 10);
  return Number.isFinite(n) ? n : fallback;
}

import { SupabaseClient } from "npm:@supabase/supabase-js@2";
import { hashPayload } from "./hash.ts";

export async function beginIdempotency(
  client: SupabaseClient,
  key: string,
  rota: string,
  parametros: Record<string, unknown>,
): Promise<{ skip: boolean; resposta?: unknown; id?: string }> {
  const parametrosHash = await hashPayload(parametros);
  const { data: existing } = await client.schema("private")
    .from("idempotency_key")
    .select("id, status, resposta")
    .eq("idempotency_key", key)
    .eq("rota", rota)
    .maybeSingle();

  if (existing?.status === "concluida") {
    return { skip: true, resposta: existing.resposta };
  }
  if (existing?.status === "executando") {
    return { skip: true, resposta: { status: "already_running", id: existing.id } };
  }

  const { data, error } = await client.schema("private")
    .from("idempotency_key")
    .insert({
      idempotency_key: key,
      rota,
      parametros_hash: parametrosHash,
      status: "executando",
    })
    .select("id")
    .single();
  if (error) throw error;
  return { skip: false, id: data.id as string };
}

export async function finishIdempotency(
  client: SupabaseClient,
  key: string,
  rota: string,
  resposta: unknown,
  httpStatus = 200,
  syncRunId?: string,
) {
  const { error } = await client.schema("private")
    .from("idempotency_key")
    .update({
      status: "concluida",
      resposta,
      http_status: httpStatus,
      sync_run_id: syncRunId ?? null,
      expires_at: new Date(Date.now() + 86400000).toISOString(),
    })
    .eq("idempotency_key", key)
    .eq("rota", rota);
  if (error) throw error;
}

const VOLATILE_KEYS = new Set([
  "last_synced_at",
  "lastSeenSyncId",
  "last_seen_sync_id",
  "created_at",
  "updated_at",
  "dataHoraAtualizacao",
]);

export async function sha256Hex(input: string | Uint8Array): Promise<string> {
  // Copy into a fresh Uint8Array so digest() accepts BufferSource under Deno/TS strict.
  const data = typeof input === "string"
    ? new TextEncoder().encode(input)
    : new Uint8Array(input);
  const hash = await crypto.subtle.digest("SHA-256", data);
  return Array.from(new Uint8Array(hash))
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
}

export function stableStringify(value: unknown): string {
  if (value === null || typeof value !== "object") {
    return JSON.stringify(value);
  }
  if (Array.isArray(value)) {
    return `[${value.map(stableStringify).join(",")}]`;
  }
  const obj = value as Record<string, unknown>;
  const keys = Object.keys(obj)
    .filter((k) => !VOLATILE_KEYS.has(k))
    .sort();
  return `{${keys.map((k) => `${JSON.stringify(k)}:${stableStringify(obj[k])}`).join(",")}}`;
}

export async function hashPayload(payload: unknown): Promise<string> {
  return sha256Hex(stableStringify(payload));
}
